package ru.zoldrax;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;
import net.minecraft.test.*;
import net.minecraft.block.*;
import net.minecraft.item.*;
import net.minecraft.entity.*;
import net.minecraft.nbt.*;
import net.minecraft.screen.*;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
public class MonkeyDecorTests implements FabricGameTest {
 void check(boolean b,String m){if(!b)throw new IllegalStateException(m);}
 DecorBlockEntity put(TestContext c,DecorKind k){var r=c.getAbsolutePos(new BlockPos(5,3,5));var b=DecorBlocks.BLOCKS.get(k);var s=b.getDefaultState();c.getWorld().setBlockState(r,s);b.onPlaced(c.getWorld(),r,s,null,new ItemStack(b));return (DecorBlockEntity)c.getWorld().getBlockEntity(r);}
 @GameTest(templateName="zoldrax_test:decor_arena") public void allRegistryFoodsHaveRealMeshes(TestContext c){try(var in=getClass().getResourceAsStream("/assets/zoldrax/food_models.json")){var json=com.google.gson.JsonParser.parseReader(new java.io.InputStreamReader(in)).getAsJsonObject();int[] count={0};net.minecraft.registry.Registries.ITEM.forEach(i->{var id=net.minecraft.registry.Registries.ITEM.getId(i);if(id.getNamespace().equals("minecraft")&&i.isFood()){check(json.has(id.toString()),"Missing edible "+id);count[0]++;try(var model=getClass().getResourceAsStream("/assets/zoldrax/models/blockbench/food/"+json.get(id.toString()).getAsString()+".bbmodel")){var data=com.google.gson.JsonParser.parseReader(new java.io.InputStreamReader(model)).getAsJsonObject();check(data.getAsJsonArray("elements").size()>=2,"Flat food model");}catch(Exception e){throw new RuntimeException(e);}}});check(count[0]==40,"Unexpected registry food count");}catch(Exception e){throw new RuntimeException(e);}c.complete();}
 @GameTest(templateName="zoldrax_test:decor_arena") public void displaysInsertOnlyOneAndSaveAllSlots(TestContext c){for(var k:new DecorKind[]{DecorKind.FOOD_SHELF,DecorKind.PREPARATION_TABLE,DecorKind.SUPPLY_BASKET,DecorKind.DRYING_RACK}){var e=put(c,k);var apples=new ItemStack(Items.APPLE,32);for(int i=0;i<k.slots;i++)check(e.insertDisplay(apples),"Cannot fill slot");check(apples.getCount()==32-k.slots,"Not one item per slot");check(!e.insertDisplay(apples),"Replaced occupied slot");var copy=(DecorBlockEntity)net.minecraft.block.entity.BlockEntity.createFromNbt(e.getPos(),e.getCachedState(),e.createNbtWithIdentifyingData());check(copy!=null&&copy.count(Items.APPLE)==k.slots,"Contents lost loading BE NBT");check(!e.insertDisplay(new ItemStack(Items.STONE)),"Nonfood accepted");var taken=e.takeDisplay(0);check(taken.getCount()==1&&e.getStack(0).isEmpty()&&e.count(Items.APPLE)==k.slots-1,"Wrong removal");c.getWorld().removeBlock(e.getPos(),false);}c.complete();}
 @GameTest(templateName="zoldrax_test:decor_arena") public void twoPlayersShareSlotsWithoutDuplication(TestContext c){var e=put(c,DecorKind.PREPARATION_TABLE);var a=c.createMockSurvivalPlayer();var b=c.createMockSurvivalPlayer();a.setStackInHand(Hand.MAIN_HAND,new ItemStack(Items.CARROT,8));b.setStackInHand(Hand.MAIN_HAND,new ItemStack(Items.BREAD,8));for(int i=0;i<4;i++){e.use(a,Hand.MAIN_HAND);e.use(b,Hand.MAIN_HAND);}check(e.count(Items.CARROT)==2&&e.count(Items.BREAD)==2,"Simultaneous insertion wrong");check(a.getMainHandStack().getCount()+b.getMainHandStack().getCount()==12,"Lost/duplicated items");c.complete();}
 @GameTest(templateName="zoldrax_test:decor_arena") public void basketOpensNineRealSlots(TestContext c){var e=put(c,DecorKind.SUPPLY_BASKET);var p=c.createMockCreativeServerPlayerInWorld();p.setPosition(Vec3d.ofCenter(e.getPos()).add(0,0,3));e.use(p,Hand.MAIN_HAND);check(p.currentScreenHandler instanceof Generic3x3ContainerScreenHandler,"No basket GUI");e.setStack(0,new ItemStack(Items.APPLE,64));e.setStack(1,new ItemStack(Items.CARROT,32));check(e.count(Items.APPLE)==64&&e.size()==9,"Bad basket stacks");p.closeHandledScreen();p.discard();c.complete();}
 @GameTest(templateName="zoldrax_test:decor_arena") public void benchSeatsTwoAndRejectsThird(TestContext c){var e=put(c,DecorKind.FESTIVAL_BENCH);var a=c.createMockCreativeServerPlayerInWorld();var b=c.createMockCreativeServerPlayerInWorld();var d=c.createMockCreativeServerPlayerInWorld();for(var p:java.util.List.of(a,b,d))p.setPosition(Vec3d.ofCenter(e.getPos()).add(0,0,3));check(e.sitOnBench(a)&&e.sitOnBench(b)&&!e.sitOnBench(d),"Bench seat limit wrong");check(a.getVehicle()!=b.getVehicle(),"Players share seat");e.sitOnBench(a);check(!a.hasVehicle()&&e.sitOnBench(d),"Seat not released");c.getWorld().breakBlock(e.getPos().east().up(),true);check(!b.hasVehicle()&&!d.hasVehicle(),"Break did not dismount");for(var p:java.util.List.of(a,b,d))p.discard();c.complete();}
 @GameTest(templateName="zoldrax_test:decor_arena",tickLimit=100) public void instrumentsEnforceCooldownAndReplay(TestContext c){var e=put(c,DecorKind.COURTYARD_GONG);check(e.strike()&&!e.strike(),"Gong cooldown missing");c.waitAndRun(18,()->{check(e.strike(),"Gong never recovers");c.getWorld().removeBlock(e.getPos(),false);var drum=put(c,DecorKind.FESTIVAL_DRUM);check(drum.strike()&&!drum.strike(),"Drum cooldown missing");c.waitAndRun(4,()->{check(drum.strike(),"Drum cannot play rhythm");c.complete();});});}
 @GameTest(templateName="zoldrax_test:decor_arena") public void noticeBoardStoresActualDocuments(TestContext c){var e=put(c,DecorKind.NOTICE_BOARD);check(e.insertDisplay(new ItemStack(Items.PAPER)),"Paper rejected");check(e.insertDisplay(new ItemStack(Items.FILLED_MAP)),"Map rejected");var book=new ItemStack(Items.WRITTEN_BOOK);book.getOrCreateNbt().putString("title","Actual decree");book.getOrCreateNbt().putString("author","Herald");var pages=new NbtList();pages.add(NbtString.of("{\"text\":\"Bring apples\"}"));book.getOrCreateNbt().put("pages",pages);check(e.insertDisplay(book),"Book rejected");var p=c.createMockCreativeServerPlayerInWorld();p.setPosition(Vec3d.ofCenter(e.getPos()).add(0,0,3));e.use(p,Hand.MAIN_HAND);check(p.currentScreenHandler instanceof LecternScreenHandler,"No book reader");check(e.getStack(2).getNbt().getString("title").equals("Actual decree"),"Invented/replaced text");p.closeHandledScreen();p.discard();c.complete();}
 @GameTest(templateName="zoldrax_test:decor_arena",tickLimit=100) public void fullInventoryReturnsFoodAsOneDrop(TestContext c){var e=put(c,DecorKind.FOOD_SHELF);e.insertDisplay(new ItemStack(Items.APPLE));var p=c.createMockCreativeServerPlayerInWorld();p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setPosition(Vec3d.ofCenter(e.getPos()).add(0,0,3));for(int i=0;i<p.getInventory().size();i++)p.getInventory().setStack(i,new ItemStack(Items.STONE,64));p.setStackInHand(Hand.OFF_HAND,ItemStack.EMPTY);p.setSneaking(true);e.use(p,Hand.OFF_HAND);c.waitAndRun(2,()->{check(e.isEmpty(),"Food not removed");check(c.getWorld().getEntitiesByClass(net.minecraft.entity.ItemEntity.class,new Box(e.getPos()).expand(8),x->x.getStack().isOf(Items.APPLE)).stream().mapToInt(x->x.getStack().getCount()).sum()==1,"Full inventory loses/duplicates food");p.discard();c.complete();});}
 @GameTest(templateName="zoldrax_test:decor_arena") public void basketDensityTracksRealCapacity(TestContext c){var e=put(c,DecorKind.SUPPLY_BASKET);check(BasketDisplayLayout.create(e).isEmpty(),"Empty basket displays food");e.setStack(0,new ItemStack(Items.APPLE));check(BasketDisplayLayout.create(e).size()==1,"One apple duplicated visually");for(int i=0;i<9;i++)e.setStack(i,new ItemStack(Items.APPLE,16));var quarter=BasketDisplayLayout.create(e);check(quarter.size()==9&&Math.abs(BasketDisplayLayout.fullness(e)-.25)<.0001,"Quarter fill wrong");for(int i=0;i<9;i++)e.setStack(i,new ItemStack(Items.CARROT,32));int half=BasketDisplayLayout.create(e).size();for(int i=0;i<9;i++)e.setStack(i,new ItemStack(Items.BREAD,64));var full=BasketDisplayLayout.create(e);check(full.size()==36&&full.size()>half&&half>quarter.size(),"Fill levels not increasing");check(full.stream().allMatch(d->d.stack().isOf(Items.BREAD)),"Fake basket contents");check(full.stream().mapToDouble(d->d.y()).max().orElseThrow()>=.79,"Full basket does not reach rim");check(e.count(Items.BREAD)==576,"Layout modified inventory");check(full.stream().allMatch(d->d.x()>.12&&d.x()<.88&&d.z()>.12&&d.z()<.88),"Food outside basket");c.complete();}

}
